// PipeName is retained for descriptor uniformity, but qmcomm2 is NOT a named-pipe
// interface: per [MS-MQMP] 2.1 the protocol is carried over ncacn_ip_tcp on an RPC
// dynamic endpoint (resolved through the endpoint mapper), with ncacn_spx as an optional
// legacy sequence. There is no fixed \pipe transport; the value below is only a stable
// short name for the interface.
const PipeName = `\qmcomm2`

// Opnums for the on-the-wire methods.
const (
	OpnumQMSendMessageInternalEx uint16 = 0
	Opnumrpc_ACSendMessageEx     uint16 = 1
	Opnumrpc_ACReceiveMessageEx  uint16 = 2
	Opnumrpc_ACCreateCursorEx    uint16 = 3
)

// Status codes returned by this interface. Every qmcomm2 method returns an HRESULT; the
// values are the Message Queuing result codes ([MS-MQMQ] 2.4, mqerror.h). Only the codes
// most relevant to the send/receive operations are enumerated here; StatusString falls
// back to the hex value for any other HRESULT.
const (
	StatusSuccess uint32 = 0x00000000 // MQ_OK

	MQ_ERROR                          uint32 = 0xC00E0001
	MQ_ERROR_QUEUE_NOT_FOUND          uint32 = 0xC00E0003
	MQ_ERROR_QUEUE_NOT_ACTIVE         uint32 = 0xC00E0004
	MQ_ERROR_INVALID_PARAMETER        uint32 = 0xC00E0006
	MQ_ERROR_INVALID_HANDLE           uint32 = 0xC00E0007
	MQ_ERROR_OPERATION_CANCELLED      uint32 = 0xC00E0008
	MQ_ERROR_SHARING_VIOLATION        uint32 = 0xC00E0009
	MQ_ERROR_SERVICE_NOT_AVAILABLE    uint32 = 0xC00E000B
	MQ_ERROR_MESSAGE_ALREADY_RECEIVED uint32 = 0xC00E001D
	MQ_ERROR_ACCESS_DENIED            uint32 = 0xC00E0025
	MQ_ERROR_INSUFFICIENT_RESOURCES   uint32 = 0xC00E0027
	MQ_ERROR_IO_TIMEOUT               uint32 = 0xC00E001B
	MQ_ERROR_TRANSACTION_USAGE        uint32 = 0xC00E0050
)

// SyntaxID returns the qmcomm2 abstract syntax identifier:
// 76d12b80-3467-11d3-91ff-0090272f9ea3, version 1.0.
func SyntaxID() syntax.SyntaxID {
	return syntax.SyntaxID{
		UUID:         guid.GUID{A: 0x76d12b80, B: 0x3467, C: 0x11d3, D: 0x91ff, E: 0x0090272f9ea3},
		MajorVersion: 1,
		MinorVersion: 0,
	}
}

// StatusString returns a mnemonic for the documented status codes, otherwise the
// hex value.
func StatusString(status uint32) string {
	switch status {
	case StatusSuccess:
		return "MQ_OK"
	case MQ_ERROR:
		return "MQ_ERROR"
	case MQ_ERROR_QUEUE_NOT_FOUND:
		return "MQ_ERROR_QUEUE_NOT_FOUND"
	case MQ_ERROR_QUEUE_NOT_ACTIVE:
		return "MQ_ERROR_QUEUE_NOT_ACTIVE"
	case MQ_ERROR_INVALID_PARAMETER:
		return "MQ_ERROR_INVALID_PARAMETER"
	case MQ_ERROR_INVALID_HANDLE:
		return "MQ_ERROR_INVALID_HANDLE"
	case MQ_ERROR_OPERATION_CANCELLED:
		return "MQ_ERROR_OPERATION_CANCELLED"
	case MQ_ERROR_SHARING_VIOLATION:
		return "MQ_ERROR_SHARING_VIOLATION"
	case MQ_ERROR_SERVICE_NOT_AVAILABLE:
		return "MQ_ERROR_SERVICE_NOT_AVAILABLE"
	case MQ_ERROR_MESSAGE_ALREADY_RECEIVED:
		return "MQ_ERROR_MESSAGE_ALREADY_RECEIVED"
	case MQ_ERROR_ACCESS_DENIED:
		return "MQ_ERROR_ACCESS_DENIED"
	case MQ_ERROR_INSUFFICIENT_RESOURCES:
		return "MQ_ERROR_INSUFFICIENT_RESOURCES"
	case MQ_ERROR_IO_TIMEOUT:
		return "MQ_ERROR_IO_TIMEOUT"
	case MQ_ERROR_TRANSACTION_USAGE:
		return "MQ_ERROR_TRANSACTION_USAGE"
	default:
		return fmt.Sprintf("0x%08x", status)
	}
}

// OpnumToName maps each on-the-wire opnum to its method name; the single source of
// truth.
var OpnumToName = map[uint16]string{
	OpnumQMSendMessageInternalEx: "QMSendMessageInternalEx",
	Opnumrpc_ACSendMessageEx:     "rpc_ACSendMessageEx",
	Opnumrpc_ACReceiveMessageEx:  "rpc_ACReceiveMessageEx",
	Opnumrpc_ACCreateCursorEx:    "rpc_ACCreateCursorEx",
}

// NameToOpnum is the reverse of OpnumToName, built at init so the two never drift.
var NameToOpnum = func() map[string]uint16 {
	m := make(map[string]uint16, len(OpnumToName))
	for op, name := range OpnumToName {
		m[name] = op
	}
	return m
}()
